            self, "Beschäftigt",
            "Es läuft noch ein Arbeitsschritt — bitte warten oder abbrechen.")
        return
    path = QFileDialog.getExistingDirectory(
        self, "Rosbag-Ordner öffnen", os.path.dirname(os.path.abspath(__file__)))
    if path:
