ThreadLocalBag.quelltext:
class ThreadLocalBag:
    """BagReader-Fassade mit einem echten Reader je Thread.

    rosbags öffnet sqlite3-Verbindungen ohne ``check_same_thread=False`` —
    ein Reader darf daher nur in seinem Erzeuger-Thread lesen. Worker- und
    Prefetch-Threads bekommen hier je einen eigenen BagReader (Aufbau des
    Kamera-Index dauert < 0,2 s).
    """

    def __init__(self, bag_path: str):
        self.bag_path = str(bag_path)
        self._local = threading.local()

    def _bag(self) -> BagReader:
        bag = getattr(self._local, "bag", None)
        if bag is None:
            bag = BagReader(self.bag_path)
            self._local.bag = bag
        return bag

    def info(self) -> BagInfo:
        return self._bag().info()

    def camera_stamps(self) -> np.ndarray:
        return self._bag().camera_stamps()

    def read_camera(self, idx: int) -> np.ndarray:
        return self._bag().read_camera(idx)

    def read_camera_jpeg(self, idx: int) -> bytes:
        return self._bag().read_camera_jpeg(idx)

    def iter_camera(self, start: int = 0, stop: int | None = None):
        return self._bag().iter_camera(start, stop)

    def read_gps(self):
        return self._bag().read_gps()

    def close(self) -> None:
        bag = getattr(self._local, "bag", None)
        if bag is not None:
            bag.close()
            self._local.bag = None

_exploration_rechnen.quelltext:
def _exploration_rechnen(bag_path: str, project, log_cb, progress_cb, cancel,
                         von: float = 0.0, bis: float = 1.0):
    """Explorationsgrad rechnen und im Projekt ablegen: (Grad|None, Hinweis).

    Laeuft im Worker-Thread. Ein Bag ohne EPIC-Daten ist der Normalfall und
    kein Fehler — dafuer kommt der Grund als Hinweistext zurueck, damit die
    Kachel ihn zeigen kann. Auch ein echter Fehler beim Rechnen darf das
    Oeffnen des Bags nicht umwerfen; er landet im Protokoll. Nur ein Abbruch
    durch den Benutzer geht weiter nach oben.
    """
    def melde(frac: float, msg: str) -> None:
        progress_cb(von + (bis - von) * frac, msg)

    try:
        grad = exploration.berechne(bag_path, progress=melde, cancel=cancel)
    except exploration.KeineExplorationsdaten as exc:
        # Negatives Ergebnis mitschreiben: beim naechsten Oeffnen genuegt der
        # Blick in den Cache, das Bag muss nicht noch einmal gelesen werden.
        try:
            project.save_exploration({"keine_daten": str(exc)})
        except OSError:
            pass
        return None, str(exc)
    except Exception as exc:  # noqa: BLE001 — fremdes Bag, viele Fehlerquellen
        if str(exc) == "Abgebrochen":
            raise
        log_cb(f"Explorationsgrad nicht berechnet: {exc}")
        return None, f"Nicht berechnet: {exc}"
    try:
        project.save_exploration(grad.als_dict())
    except OSError as exc:
        log_cb(f"exploration.json nicht geschrieben: {exc}")
    return grad, ""

_exploration_holen.quelltext:
def _exploration_holen(bag_path: str, project, log_cb, progress_cb, cancel,
                       von: float = 0.0, bis: float = 1.0):
    """Wie :func:`_exploration_rechnen`, nimmt aber den Cache, wenn es ihn gibt."""
    gespeichert = project.load_exploration()
    if gespeichert:
        if gespeichert.get("keine_daten"):
            return None, str(gespeichert["keine_daten"])
        try:
            return exploration.Explorationsgrad.aus_dict(gespeichert), ""
        except (TypeError, ValueError) as exc:
            log_cb(f"Gespeicherter Explorationsgrad unbrauchbar ({exc}) — "
                   "wird neu gerechnet.")
    return _exploration_rechnen(bag_path, project, log_cb, progress_cb, cancel,
                                von, bis)
